import { describe, it, expect } from 'vitest';
import * as fs from 'fs';
import * as path from 'path';

describe('Forge POC Verification Suite', () => {
  const mockTodoContent = `# Project TODO

## Immediate
- [ ] Test system orchestrator

## Next
- [ ] Multi-agent support

## Later
- [ ] Add assayer clustering

## Architecture Notes
- Enforce layout separation rules.

## Generated By
Forge POC run: run-test-123
`;

  it('verifies TODO.md contains all required sections', () => {
    const required = ['# Project TODO', '## Immediate', '## Next', '## Later', '## Architecture Notes', '## Generated By'];
    const missing = required.filter(sec => !mockTodoContent.includes(sec));
    expect(missing.length).toBe(0);
  });

  it('fails verification if any section is missing', () => {
    const brokenTodo = `# Project TODO\n## Immediate\n`;
    const required = ['# Project TODO', '## Immediate', '## Next', '## Later', '## Architecture Notes', '## Generated By'];
    const missing = required.filter(sec => !brokenTodo.includes(sec));
    expect(missing.length).toBeGreaterThan(0);
  });
});
